export interface Component { init(): Promise<void>; handle(req: Request): Promise<Response> }
type Entry = { name: string; specifier: string };

export async function link(entry: Entry, repo: Map<string, Component>) {
  const mod: unknown = await import(/* @vite-ignore */ entry.specifier);
  const factory = (mod as { create?: () => Component }).create;
  if (!factory) throw new Error(`${entry.name}: module does not export create()`);
  repo.set(entry.name, factory());
}
